import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';
import 'package:litch_mobile/src/models/game_archive.dart';
import 'package:litch_mobile/src/services/game_history_protocol.dart';
import 'package:litch_mobile/src/services/game_history_segment_importer.dart';
import 'package:litch_mobile/src/services/game_history_sync_state_store.dart';
import 'package:litch_mobile/src/services/game_library_repository.dart';
import 'package:litch_mobile/src/services/game_library_store.dart';

// Generated by test_game_history_rolling_tail through real physical occupancy,
// settings save/reload, capture, and the native bounded journal segment encoder.
// This covers the durable importer seam, not BLE scheduling or physical LEDs.
void main() {
  final String? wire = Platform.environment['LITCH_HISTORY_REBASE_WIRE'];
  test(
    'native long Duck game Undo preserves the complete archived prefix',
    () async {
      final Directory root = await Directory.systemTemp.createTemp(
        'litch-native-rebase-',
      );
      GameLibraryRepository repository = GameLibraryRepository(
        GameLibraryStore(Directory('${root.path}/library')),
      );
      try {
        final GameHistoryDurableSegmentProcessor processor =
            GameHistoryDurableSegmentProcessor(
              importer: GameHistorySegmentImporter(repository),
              stateStore: GameHistorySyncStateStore(
                Directory('${root.path}/cursors'),
              ),
            );
        bool sawOriginal = false;
        for (final String line in await File(wire!).readAsLines()) {
          final Map<String, dynamic> value =
              jsonDecode(line) as Map<String, dynamic>;
          final String hex = value['hex'] as String;
          final Uint8List bytes = Uint8List.fromList(<int>[
            for (int i = 0; i < hex.length; i += 2)
              int.parse(hex.substring(i, i + 2), radix: 16),
          ]);
          final GameHistorySegmentDescriptor descriptor =
              GameHistorySegmentDescriptor(
                encodedBytes: value['encodedBytes'] as int,
                recordCount: value['recordCount'] as int,
                flags: value['flags'] as int,
                firstOutboxSequence: value['firstOutboxSequence'] as int,
                crc32: value['crc32'] as int,
              );
          Future<GameHistoryDurableSegmentResult> receive() =>
              processor.process(
                boardIdentity: 'native-rolling-duck-board',
                journalId: '0102030405060708',
                descriptor: descriptor,
                bytes: bytes,
                observedAt: DateTime.utc(2026, 9, 7),
              );
          await receive();
          final GameArchive archive = (await repository.load()).games.single;
          expect(archive.captureQuality, GameCaptureQuality.complete);
          expect(archive.positions.first.ply, 0);
          if (archive.currentPly == 136) sawOriginal = true;
          expect((await receive()).alreadyDurable, isTrue);
        }
        expect(
          sawOriginal,
          isTrue,
          reason: 'The full original line must precede Undo',
        );
        await repository.close();
        repository = GameLibraryRepository(
          GameLibraryStore(Directory('${root.path}/library')),
        );
        final GameArchive restored = (await repository.load()).games.single;
        expect(restored.currentPly, 135);
        expect(restored.captureQuality, GameCaptureQuality.complete);
        expect(restored.positions, hasLength(136));
        expect(restored.transitions, hasLength(135));
        for (final ArchivedPosition position in restored.positions) {
          final List<String> fields = position.fen.split(' ');
          expect(int.parse(fields[4]), position.ply <= 132 ? position.ply : 0);
          expect(int.parse(fields[5]), position.ply ~/ 2 + 1);
        }
      } finally {
        await repository.close();
        await root.delete(recursive: true);
      }
    },
    skip: wire == null
        ? 'Set LITCH_HISTORY_REBASE_WIRE to the native segment artifact'
        : false,
  );
}
